        return None

    rows_min, rows_max = min(r for r, c in positions), max(r for r, c in positions)
    cols_min, cols_max = min(c for r, c in positions), max(c for r, c in positions)

    height = rows_max - rows_min + 1
    width = cols_max - cols_min + 1

    # Check if it's a hollow rectangle
    # A hollow rectangle of height h and width w would have 2*(h+w) - 4 perimeter cells
    if height == 1 or width == 1:
        is_hollow = 0 < height < 2 or 0 < width < 2
    else:
        expected_perimeter = 2 * (height + width) - 4
        actual_cells = count
        is_hollow = actual_cells == expected_perimeter

    return {
        'color': color,
        'positions': positions,
        'bbox': (rows_min, rows_max, cols_min, cols_max),
        'height': height,
        'width': width,
        'pixels': count
    }

